import { Component, type ErrorInfo, type ReactNode } from 'react';
import { AlertTriangle, RefreshCw, Loader, AlertCircle } from 'lucide-react';
import { AppError, errorLogger, generateErrorId } from '../lib/errorHandler';

interface ErrorBoundaryProps {
  children: ReactNode;
  /** Custom fallback UI. Receives the error and a reset handler. */
  fallback?: (error: AppError, resetErrorBoundary: () => void) => ReactNode;
  /** Called when an error is caught, after logging. */
  onError?: (error: AppError, info: ErrorInfo) => void;
}

interface ErrorBoundaryState {
  error: AppError | null;
}

/**
 * ErrorBoundary — a React class component that catches JavaScript errors
 * anywhere in the child component tree, logs them to Supabase + Firebase Analytics,
 * and displays a user-friendly fallback UI.
 *
 * Supports a custom `fallback` render prop, or uses the default fallback which
 * includes a "Try Again" button and a "Report This Problem" link.
 *
 * Usage:
 * ```tsx
 * <ErrorBoundary>
 *   <MyPage />
 * </ErrorBoundary>
 * ```
 */
export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { error: null };

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    const appError =
      error instanceof AppError
        ? error
        : new AppError({
            code: 'RENDER_ERROR',
            message: 'Something went wrong while displaying this page.',
            isOperational: false,
            cause: error,
            context: { componentStack: 'See errorInfo' },
          });
    return { error: appError };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const appError = this.state.error ?? new AppError({
      code: 'RENDER_ERROR',
      message: error.message,
      isOperational: false,
      cause: error,
    });

    // Attach component stack to context
    (appError as AppError & { context: Record<string, unknown> }).context = {
      ...appError.context,
      componentStack: info.componentStack,
    };

    // Log to Supabase + Firebase Analytics (fire-and-forget)
    errorLogger.log(appError, { source: 'ErrorBoundary' });

    this.props.onError?.(appError, info);
  }

  resetErrorBoundary = (): void => {
    this.setState({ error: null });
  };

  render(): ReactNode {
    if (this.state.error) {
      if (this.props.fallback) {
        return this.props.fallback(this.state.error, this.resetErrorBoundary);
      }
      return <DefaultFallback error={this.state.error} resetErrorBoundary={this.resetErrorBoundary} />;
    }
    return this.props.children;
  }
}

/**
 * DefaultFallback — the standard error UI shown when no custom fallback is provided.
 */
function DefaultFallback({ error, resetErrorBoundary }: { error: AppError; resetErrorBoundary: () => void }) {
  return (
    <div className="min-h-[60vh] flex items-center justify-center px-4 py-10">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-lg border border-slate-200 p-8 text-center animate-fade-in">
        <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-5">
          <AlertTriangle className="w-8 h-8 text-red-500" />
        </div>
        <h1 className="text-xl font-serif font-bold text-navy-900 mb-2">Something went wrong</h1>
        <p className="text-slate-500 text-sm mb-4">{error.message}</p>

        <div className="bg-slate-50 border border-slate-200 rounded-lg p-3 mb-6">
          <p className="text-xs text-slate-400">
            Error reference: <span className="font-mono font-semibold text-slate-600">{error.errorId}</span>
          </p>
          <p className="text-xs text-slate-400 mt-1">
            If the problem persists, please share this reference with support.
          </p>
        </div>

        <div className="flex flex-col sm:flex-row gap-3 justify-center">
          <button
            onClick={resetErrorBoundary}
            className="btn-primary inline-flex items-center justify-center gap-2"
          >
            <RefreshCw className="w-4 h-4" /> Try Again
          </button>
          <a
            href={`mailto:aizawlbiblecollege24@gmail.com?subject=Error Report ${error.errorId}&body=Error ID: ${error.errorId}%0D%0A%0D%0APlease describe what you were doing when this error occurred:%0D%0A`}
            className="btn-secondary inline-flex items-center justify-center gap-2"
          >
            <AlertCircle className="w-4 h-4" /> Report This Problem
          </a>
        </div>
      </div>
    </div>
  );
}

/**
 * Convenience wrapper for async route loaders that may reject.
 * Usage in route definitions: `loader: asyncLoaderWrapper(myLoader)`
 */
export function asyncLoaderWrapper<T extends (...args: never[]) => Promise<unknown>>(
  loader: T,
): T {
  return (async (...args: Parameters<T>) => {
    try {
      return await loader(...args);
    } catch (err) {
      const errorId = generateErrorId();
      const appError =
        err instanceof AppError
          ? err
          : new AppError({
              code: 'ROUTE_LOADER_ERROR',
              message: 'Failed to load this page.',
              isOperational: false,
              cause: err instanceof Error ? err : new Error(String(err)),
            });
      errorLogger.log(appError, { source: 'asyncLoaderWrapper', errorId });
      throw appError;
    }
  }) as T;
}

/** Loading indicator shown while the boundary is resetting. */
export function ErrorBoundaryResetLoader() {
  return (
    <div className="flex items-center justify-center py-10">
      <Loader className="w-6 h-6 text-navy-700 animate-spin" />
    </div>
  );
}

import { useState } from 'react';
import { z } from 'zod';
import { Loader, Save, User } from 'lucide-react';
import { ErrorBoundary } from './ErrorBoundary';
import { useApiRequest } from '../hooks/useApiRequest';
import { useFormValidation } from '../hooks/useFormValidation';
import { useNetworkStatus } from '../hooks/useNetworkStatus';
import { useToast } from './Toast';
import ErrorMessage from './ErrorMessage';
import ValidationErrorList, { InlineError } from './ValidationErrorList';
import { safeSupabaseCall } from '../lib/supabaseErrorHandler';
import { supabase, type Profile } from '../lib/supabase';
import type { AppError } from '../lib/errorHandler';

// ── Example 1: Wrapping a page with ErrorBoundary ─────────────────────────

/**
 * Example 1 — Wrapping a page component with `ErrorBoundary`.
 * Any render error in `ProfilePage` is caught and shows the fallback UI.
 */
export function Example1_ErrorBoundary() {
  return (
    <ErrorBoundary>
      <ProfilePage />
    </ErrorBoundary>
  );
}

function ProfilePage() {
  return (
    <div className="p-6">
      <h2 className="text-xl font-serif font-bold text-navy-900">Profile</h2>
      <p className="text-slate-500 text-sm mt-2">This page is wrapped in an ErrorBoundary.</p>
    </div>
  );
}

// ── Example 2: useApiRequest with Supabase + error display ─────────────────

/**
 * Example 2 — Using `useApiRequest` to fetch data from Supabase with
 * automatic retry, cancellation, and error display.
 */
export function Example2_ApiRequest() {
  const { data, error, isLoading, retry } = useApiRequest<Profile[]>(async (signal) => {
    const result = await supabase
      .from('profiles')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(5)
      .abortSignal(signal);
    if (result.error) throw result.error;
    return result.data ?? [];
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-10">
        <Loader className="w-6 h-6 text-navy-700 animate-spin" />
      </div>
    );
  }

  if (error) {
    return <ErrorMessage error={error} onRetry={retry} />;
  }

  return (
    <div className="space-y-3">
      <h2 className="text-lg font-serif font-bold text-navy-900">Recent Users</h2>
      {data?.map((profile) => (
        <div key={profile.id} className="flex items-center gap-3 p-3 bg-white rounded-lg border border-slate-200">
          <div className="w-8 h-8 rounded-full bg-navy-100 flex items-center justify-center">
            <User className="w-4 h-4 text-navy-600" />
          </div>
          <div>
            <p className="text-sm font-medium text-navy-900">{profile.full_name ?? 'Unnamed'}</p>
            <p className="text-xs text-slate-500">{profile.email}</p>
          </div>
        </div>
      ))}
    </div>
  );
}

// ── Example 3: Form with Zod validation + inline errors ────────────────────

const contactSchema = z.object({
  name: z.string().min(2, 'Name must be at least 2 characters'),
  email: z.string().email('Please enter a valid email address'),
  message: z.string().min(10, 'Message must be at least 10 characters'),
});

type ContactForm = z.infer<typeof contactSchema>;

/**
 * Example 3 — A form using `useFormValidation` with a Zod schema,
 * showing inline validation errors per field.
 */
export function Example3_FormValidation() {
  const { errors, validate, validateField, clearError, isValid } = useFormValidation<ContactForm>(contactSchema);
  const [form, setForm] = useState<ContactForm>({ name: '', email: '', message: '' });
  const [submitted, setSubmitted] = useState(false);
  const toast = useToast();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate(form)) {
      toast.success('Message sent!', 'We will get back to you soon.');
      setSubmitted(true);
    } else {
      toast.error('Please fix the errors', 'Some fields need your attention.');
    }
  };

  if (submitted) {
    return (
      <div className="p-6 bg-green-50 border border-green-200 rounded-xl text-center">
        <p className="text-green-700 font-medium">Thank you! Your message has been sent.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4 max-w-md">
      <div>
        <label className="label">Name</label>
        <input
          type="text"
          value={form.name}
          onChange={(e) => {
            setForm({ ...form, name: e.target.value });
            if (errors.name) clearError('name');
          }}
          onBlur={(e) => validateField('name', e.target.value)}
          className="input-field"
          placeholder="Your name"
        />
        <InlineError message={errors.name?.[0]} />
      </div>

      <div>
        <label className="label">Email</label>
        <input
          type="email"
          value={form.email}
          onChange={(e) => {
            setForm({ ...form, email: e.target.value });
            if (errors.email) clearError('email');
          }}
          onBlur={(e) => validateField('email', e.target.value)}
          className="input-field"
          placeholder="you@example.com"
        />
        <InlineError message={errors.email?.[0]} />
      </div>

      <div>
        <label className="label">Message</label>
        <textarea
          value={form.message}
          onChange={(e) => {
            setForm({ ...form, message: e.target.value });
            if (errors.message) clearError('message');
          }}
          onBlur={(e) => validateField('message', e.target.value)}
          className="input-field resize-none min-h-24"
          placeholder="Your message..."
        />
        <InlineError message={errors.message?.[0]} />
      </div>

      {Object.keys(errors).length > 0 && (
        <ValidationErrorList errors={errors} onDismiss={(field) => clearError(field as keyof ContactForm)} />
      )}

      <button type="submit" disabled={!isValid} className="btn-primary inline-flex items-center gap-2">
        <Save className="w-4 h-4" /> Send Message
      </button>
    </form>
  );
}

// ── Example 4: OfflineBanner with useNetworkStatus ─────────────────────────

/**
 * Example 4 — The `OfflineBanner` rendering conditionally based on
 * `useNetworkStatus`. The banner auto-shows when offline.
 */
export function Example4_OfflineBanner() {
  const { isOnline, wasOffline, connectionType } = useNetworkStatus();

  return (
    <div className="p-6 bg-slate-50 rounded-xl border border-slate-200">
      <h2 className="text-lg font-serif font-bold text-navy-900 mb-3">Network Status</h2>
      <div className="space-y-2 text-sm">
        <p className="flex items-center gap-2">
          <span className={`w-2.5 h-2.5 rounded-full ${isOnline ? 'bg-green-500' : 'bg-red-500'}`} />
          <span className="font-medium text-navy-900">{isOnline ? 'Online' : 'Offline'}</span>
        </p>
        {wasOffline && (
          <p className="text-amber-600 text-xs">You were recently offline — data may have been queued.</p>
        )}
        <p className="text-slate-500 text-xs">Connection type: {connectionType}</p>
      </div>
      <p className="text-xs text-slate-400 mt-3">
        The OfflineBanner component at the top of the page shows automatically when offline.
      </p>
    </div>
  );
}

// ── Example 5: safeSupabaseCall in a data-fetching function ────────────────

/**
 * Example 5 — Using `safeSupabaseCall` in a data-fetching function.
 * The discriminated union return type means `data` is only accessible
 * when `error` is `null`.
 */
export async function fetchUserProfile(userId: string) {
  const result = await safeSupabaseCall<Profile>(
    supabase.from('profiles').select('*').eq('id', userId).maybeSingle() as PromiseLike<{ data: Profile | null; error: { code?: string; message: string; details?: string } | null }>,
    { userId, operation: 'fetchUserProfile' },
  );

  if (result.error) {
    // `result.data` is null here, `result.error` is an AppError
    return { profile: null, error: result.error };
  }

  // `result.data` is typed as Profile, `result.error` is null
  return { profile: result.data, error: null };
}

/**
 * Example5_Component — demonstrates calling `fetchUserProfile` and
 * rendering the result or error.
 */
export function Example5_SafeSupabaseCall() {
  const [loading, setLoading] = useState(false);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [error, setError] = useState<AppError | null>(null);

  const loadProfile = async () => {
    setLoading(true);
    setError(null);
    const { profile: p, error: e } = await fetchUserProfile('00000000-0000-0000-0000-000000000000');
    setProfile(p);
    setError(e);
    setLoading(false);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader className="w-6 h-6 text-navy-700 animate-spin" />
      </div>
    );
  }

  if (error) {
    return <ErrorMessage error={error} onRetry={loadProfile} />;
  }

  if (profile) {
    return (
      <div className="p-4 bg-white rounded-lg border border-slate-200">
        <p className="text-sm font-medium text-navy-900">{profile.full_name}</p>
        <p className="text-xs text-slate-500">{profile.email}</p>
      </div>
    );
  }

  return (
    <button onClick={loadProfile} className="btn-secondary">
      Load Profile (demo)
    </button>
  );
}

import { useState, useEffect, useRef } from 'react';
import { Link, NavLink, useLocation } from 'react-router-dom';
import { Menu, X, ChevronDown, User, LogOut, LayoutDashboard, CreditCard, Bell, BellOff, Download, UserPlus, GraduationCap } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { useNotifications } from '../contexts/NotificationContext';

function timeAgo(dateStr: string): string {
  const diff = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  if (days < 7) return `${days}d ago`;
  return new Date(dateStr).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' });
}

const navLinks = [
  { label: 'Home', path: '/' },
  { label: 'About', path: '/about' },
  {
    label: 'College',
    children: [
      { label: 'Prologue', path: '/prologue' },
      { label: 'Doctrine', path: '/doctrine' },
      { label: 'Academic Info', path: '/academics' },
      { label: 'Our Faculty', path: '/teachers' },
      { label: 'Board of Management', path: '/board' },
    ],
  },
  { label: 'Gallery', path: '/gallery' },
  { label: 'Blog', path: '/blog' },
  { label: 'Downloads', path: '/downloads' },
  { label: 'Apply', path: '/apply' },
];

const navLinksAuth = [
  { label: 'Notices', path: '/notices' },
  { label: 'Forum', path: '/forum' },
];

const navLinksPublic = [
  { label: 'Contact', path: '/contact' },
];

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [dropdown, setDropdown] = useState('');
  const [notifOpen, setNotifOpen] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const { user, profile, signOut } = useAuth();
  const { notifications, unreadCount, adminUnreadMessages, markAsRead, markAllAsRead, pushSupported, pushEnabled, enablePush } = useNotifications();
  const location = useLocation();
  const navRef = useRef<HTMLElement>(null);
  const notifRef = useRef<HTMLDivElement>(null);
  const mobileNotifRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setOpen(false);
    setDropdown('');
  }, [location]);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (navRef.current && !navRef.current.contains(e.target as Node)) {
        setDropdown('');
      }
      const inDesktopNotif = notifRef.current?.contains(e.target as Node);
      const inMobileNotif = mobileNotifRef.current?.contains(e.target as Node);
      if (!inDesktopNotif && !inMobileNotif) {
        setNotifOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const handler = (e: Event) => { e.preventDefault(); setDeferredPrompt(e); };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  async function installPWA() {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    await deferredPrompt.userChoice;
    setDeferredPrompt(null);
  }

  function toggleDropdown(label: string) {
    setDropdown((prev) => (prev === label ? '' : label));
  }

  const totalBadge = unreadCount + (profile?.role === 'admin' ? adminUnreadMessages : 0);

  return (
    <header
      ref={navRef}
      className={`sticky top-0 z-50 transition-all duration-300 ${
        scrolled ? 'bg-navy-950 shadow-lg' : 'bg-navy-950'
      }`}
    >
      {/* Top bar */}
      <div className="bg-gold-500 py-1 px-2 text-center overflow-hidden">
        <p className="hidden md:block text-navy-950 text-xs font-medium truncate">
          Accredited by Pentecostal Association for Theological Accreditation (PATA) | Member of Evangelical Theological Colleges Association – NEI | Estd. 1998
        </p>
        <div className="md:hidden overflow-hidden">
          <span className="marquee-ticker text-navy-950 text-xs font-medium">
            Accredited by Pentecostal Association for Theological Accreditation (PATA) | Member of Evangelical Theological Colleges Association – NEI | Estd. 1998
          </span>
        </div>
      </div>

      <nav className="w-full max-w-screen-xl mx-auto px-3 md:px-4">
        <div className="flex items-center justify-between h-16 gap-2 min-w-0">
          {/* Logo */}
          <Link to="/" className="flex items-center gap-2 flex-shrink-0">
            <img
              src="/logo.png"
              alt="Aizawl Bible College"
              className="w-9 h-9 md:w-10 md:h-10 rounded-full object-cover border-2 border-gold-400"
            />
            <div className="hidden lg:block">
              <p className="text-white font-serif font-bold text-sm leading-tight">Aizawl Bible College</p>
              <p className="text-gold-300 text-xs leading-tight">Assemblies of God, Mizoram</p>
            </div>
          </Link>

          {/* Desktop nav */}
          <div className="hidden md:flex items-center flex-1 min-w-0 gap-0.5 px-1">
            {navLinks.map((link) =>
              link.children ? (
                <div
                  key={link.label}
                  className="relative flex-shrink-0"
                  onMouseEnter={() => setDropdown(link.label)}
                  onMouseLeave={() => setDropdown('')}
                >
                  <button
                    onClick={() => setDropdown(link.label)}
                    className="flex items-center gap-0.5 px-1.5 py-1.5 lg:px-2.5 text-slate-200 hover:text-white text-xs lg:text-sm font-medium rounded-lg hover:bg-white/10 transition-colors whitespace-nowrap"
                  >
                    {link.label}
                    <ChevronDown className={`w-3 h-3 transition-transform ${dropdown === link.label ? 'rotate-180' : ''}`} />
                  </button>
                  {dropdown === link.label && (
                    <div className="absolute top-full left-0 mt-1 w-48 bg-white rounded-xl shadow-xl border border-slate-200 py-1 z-[60]">
                      {link.children.map((child) => (
                        <NavLink
                          key={child.path}
                          to={child.path}
                          className={({ isActive }) =>
                            `block px-4 py-2.5 text-sm transition-colors ${
                              isActive ? 'text-navy-800 bg-navy-50 font-medium' : 'text-slate-700 hover:bg-slate-50 hover:text-navy-800'
                            }`
                          }
                        >
                          {child.label}
                        </NavLink>
                      ))}
                    </div>
                  )}
                </div>
              ) : (
                <NavLink
                  key={link.path}
                  to={link.path!}
                  className={({ isActive }) =>
                    `flex-shrink-0 px-1.5 py-1.5 lg:px-2.5 text-xs lg:text-sm font-medium rounded-lg transition-colors whitespace-nowrap ${
                      isActive
                        ? 'text-gold-400 bg-white/10'
                        : 'text-slate-200 hover:text-white hover:bg-white/10'
                    }`
                  }
                >
                  {link.label}
                </NavLink>
              )
            )}
            {user && navLinksAuth.map((link) => (
              <NavLink
                key={link.path}
                to={link.path!}
                className={({ isActive }) =>
                  `flex-shrink-0 px-1.5 py-1.5 lg:px-2.5 text-xs lg:text-sm font-medium rounded-lg transition-colors whitespace-nowrap ${
                    isActive
                      ? 'text-gold-400 bg-white/10'
                      : 'text-slate-200 hover:text-white hover:bg-white/10'
                  }`
                }
              >
                {link.label}
              </NavLink>
            ))}
            {navLinksPublic.map((link) => (
              <NavLink
                key={link.path}
                to={link.path!}
                className={({ isActive }) =>
                  `flex-shrink-0 px-1.5 py-1.5 lg:px-2.5 text-xs lg:text-sm font-medium rounded-lg transition-colors whitespace-nowrap ${
                    isActive
                      ? 'text-gold-400 bg-white/10'
                      : 'text-slate-200 hover:text-white hover:bg-white/10'
                  }`
                }
              >
                {link.label}
              </NavLink>
            ))}
          </div>

          {/* Desktop: Auth buttons / user menu */}
          <div className="hidden md:flex items-center gap-1 flex-shrink-0">
            {user ? (
              <>
                {/* Desktop notification bell */}
                <div className="relative" ref={notifRef}>
                  <button
                    onClick={() => setNotifOpen((v) => !v)}
                    className="relative p-1.5 text-white hover:bg-white/10 rounded-lg transition-colors"
                    title={`${totalBadge} unread notification${totalBadge !== 1 ? 's' : ''}`}
                  >
                    <Bell className="w-4 h-4" />
                    {totalBadge > 0 && (
                      <span className="absolute -top-0.5 -right-0.5 min-w-[16px] h-4 bg-amber-500 text-white text-[10px] font-bold flex items-center justify-center rounded-full px-1 animate-pulse">
                        {totalBadge > 9 ? '9+' : totalBadge}
                      </span>
                    )}
                  </button>
                  {notifOpen && (
                    <div className="absolute right-0 top-full mt-2 w-80 bg-white rounded-xl shadow-2xl border border-slate-200 z-50 overflow-hidden">
                      <div className="flex items-center justify-between px-4 py-3 border-b border-slate-100">
                        <span className="font-serif font-bold text-navy-900 text-sm">Notifications</span>
                        {unreadCount > 0 && (
                          <button onClick={markAllAsRead} className="text-xs text-blue-600 hover:text-blue-800 font-medium">Mark all read</button>
