  const [loading, setLoading] = useState(true);
  const [profileLoading, setProfileLoading] = useState(false);
  const [profileError, setProfileError] = useState<string | null>(null);
  const profileChannelRef = useRef<RealtimeChannel | null>(null);

  async function fetchProfile(userId: string) {
    setProfileLoading(true);
    setProfileError(null);

    // Check that the client has an active session before querying
    const { data: { session: currentSession } } = await supabase.auth.getSession();

    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .maybeSingle();

    if (error) {
      const msg = `DB error: ${error.message} (code: ${error.code}) — session uid: ${currentSession?.user?.id ?? 'none'}`;
      console.error('[fetchProfile]', msg);
      setProfileError(msg);
    } else if (!data) {
      // Row not found — try by email as a fallback
      const email = currentSession?.user?.email;
      if (email) {
        const { data: byEmail, error: emailErr } = await supabase
          .from('profiles')
          .select('*')
          .eq('email', email)
          .maybeSingle();
        if (byEmail && !emailErr) {
          setProfile(byEmail);
          setProfileLoading(false);
          return;
        }
      }
      setProfileError(`No profile row found for user ID: ${userId}`);
      console.warn('[fetchProfile] No profile found for', userId);
    } else {
      setProfile(data);
    }

    setProfileLoading(false);
  }

  async function refreshProfile() {
    if (user) await fetchProfile(user.id);
  }

  // Set up realtime subscription for profile changes
  useEffect(() => {
    if (user?.id && !profileChannelRef.current) {
      profileChannelRef.current = supabase
        .channel(`profile-${user.id}`)
        .on(
          'postgres_changes',
          {
            event: 'UPDATE',
            schema: 'public',
            table: 'profiles',
            filter: `id=eq.${user.id}`,
          },
          (payload) => {
            setProfile(payload.new as Profile);
          }
        )
        .subscribe();
    }

    return () => {
      if (profileChannelRef.current) {
        supabase.removeChannel(profileChannelRef.current);
        profileChannelRef.current = null;
      }
    };
  }, [user?.id]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      (async () => {
        setSession(session);
        setUser(session?.user ?? null);
        if (session?.user) {
          await fetchProfile(session.user.id);
        }
        setLoading(false);
      })();
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'INITIAL_SESSION') return;
      (async () => {
        setSession(session);
        setUser(session?.user ?? null);
        if (session?.user) {
          await fetchProfile(session.user.id);
        } else {
          setProfile(null);
          setProfileError(null);
        }
        setLoading(false);
      })();
    });

    return () => subscription.unsubscribe();
  }, []);

  async function signOut() {
    await supabase.auth.signOut();
  }

  return (
    <AuthContext.Provider value={{ session, user, profile, loading, profileLoading, profileError, signOut, refreshProfile }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}

import { createContext, useContext, useEffect, useRef, useState, useCallback, type ReactNode } from 'react';
import { supabase, type Notification } from '../lib/supabase';
import { useAuth } from './AuthContext';
import { subscribeToPush, unsubscribeFromPush, listenForForegroundPush, isNotificationSupported } from '../lib/push';

type NotificationContextType = {
  notifications: Notification[];
  unreadCount: number;
  adminUnreadMessages: number;
  loading: boolean;
  notifLoading: boolean;
  pushSupported: boolean;
  pushEnabled: boolean;
  pushError: string | null;
  markAsRead: (id: string) => Promise<void>;
  markAllAsRead: () => Promise<void>;
  enablePush: () => Promise<{ success: boolean; error?: string }>;
  disablePush: () => Promise<{ success: boolean; error?: string }>;
  refresh: () => void;
};

const NotificationContext = createContext<NotificationContextType | undefined>(undefined);

export function NotificationProvider({ children }: { children: ReactNode }) {
  const { profile } = useAuth();
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [adminUnreadMessages, setAdminUnreadMessages] = useState(0);
  const [loading, setLoading] = useState(false);
  const [pushSupported, setPushSupported] = useState(false);
  const [pushEnabled, setPushEnabled] = useState(false);
  const [pushError, setPushError] = useState<string | null>(null);
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);

  const loadNotifications = useCallback(async () => {
    if (!profile?.id) return;
    setLoading(true);
    const { data } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', profile.id)
      .order('created_at', { ascending: false })
      .limit(20);
    const notifs = (data as Notification[]) ?? [];
    setNotifications(notifs);
    setUnreadCount(notifs.filter((n) => !n.is_read).length);

    // Admin: load unread contact messages count
    if (profile.role === 'admin') {
      const { count } = await supabase
        .from('contact_messages')
        .select('*', { count: 'exact', head: true })
        .eq('is_read', false);
      setAdminUnreadMessages(count ?? 0);
    } else {
      setAdminUnreadMessages(0);
    }

    setLoading(false);
  }, [profile?.id, profile?.role]);

  // Load notifications + set up realtime subscription
  useEffect(() => {
    if (!profile?.id) {
      setNotifications([]);
      setUnreadCount(0);
      return;
    }

    loadNotifications();

    // Realtime subscription for new notifications
    const channel = supabase
      .channel(`notifications:${profile.id}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'notifications',
          filter: `user_id=eq.${profile.id}`,
        },
        (payload) => {
          const newNotif = payload.new as Notification;
          setNotifications((prev) => [newNotif, ...prev].slice(0, 20));
          setUnreadCount((c) => c + 1);
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'notifications',
          filter: `user_id=eq.${profile.id}`,
        },
        (payload) => {
          const updated = payload.new as Notification;
          setNotifications((prev) => prev.map((n) => (n.id === updated.id ? updated : n)));
          setUnreadCount((c) =>
            updated.is_read ? Math.max(0, c - 1) : c
          );
        }
      )
      .subscribe();

    channelRef.current = channel;

    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, [profile?.id, loadNotifications]);

  // Check push support + whether already subscribed
  useEffect(() => {
    let mounted = true;
    (async () => {
      const supported = await isNotificationSupported();
      if (!mounted) return;
      setPushSupported(supported);

      if (supported && profile?.id) {
        const { data } = await supabase
          .from('push_subscriptions')
          .select('id')
          .eq('user_id', profile.id)
          .limit(1);
        if (mounted) setPushEnabled((data?.length ?? 0) > 0);
      } else {
        if (mounted) setPushEnabled(false);
      }
    })();
    return () => { mounted = false; };
  }, [profile?.id]);

  // Listen for foreground push messages
  useEffect(() => {
    listenForForegroundPush(() => {
      loadNotifications();
    });
  }, [loadNotifications]);

  const markAsRead = useCallback(async (id: string) => {
    await supabase.from('notifications').update({ is_read: true }).eq('id', id);
    setNotifications((prev) => prev.map((n) => (n.id === id ? { ...n, is_read: true } : n)));
    setUnreadCount((c) => Math.max(0, c - 1));
  }, []);

  const markAllAsRead = useCallback(async () => {
    if (!profile?.id) return;
    await supabase
      .from('notifications')
      .update({ is_read: true })
      .eq('user_id', profile.id)
      .eq('is_read', false);
    // Clear from display so new notifications have room to show
    setNotifications([]);
    setUnreadCount(0);
  }, [profile?.id]);

  const enablePush = useCallback(async (): Promise<{ success: boolean; error?: string }> => {
    if (!profile?.id) return { success: false, error: 'Not logged in' };
    setPushError(null);
    const result = await subscribeToPush(profile.id);
    if (result.success) {
      setPushEnabled(true);
    } else {
      setPushError(result.error || 'Failed to enable push notifications');
    }
    return result;
  }, [profile?.id]);

  const disablePush = useCallback(async (): Promise<{ success: boolean; error?: string }> => {
    if (!profile?.id) return { success: false, error: 'Not logged in' };
    setPushError(null);
    const result = await unsubscribeFromPush(profile.id);
    if (result.success) {
      setPushEnabled(false);
    } else {
      setPushError(result.error || 'Failed to disable push notifications');
    }
    return result;
  }, [profile?.id]);

  return (
    <NotificationContext.Provider
      value={{
        notifications,
        unreadCount,
        adminUnreadMessages,
        loading,
        notifLoading: loading,
        pushSupported,
        pushEnabled,
        pushError,
        markAsRead,
        markAllAsRead,
        enablePush,
        disablePush,
        refresh: loadNotifications,
      }}
    >
      {children}
    </NotificationContext.Provider>
  );
}

export function useNotifications() {
  const ctx = useContext(NotificationContext);
  if (!ctx) throw new Error('useNotifications must be used within NotificationProvider');
  return ctx;
}

