async function ensureMessaging(): Promise<Messaging | null> {
  if (messaging) return messaging;
  const supported = await isSupported();
  if (!supported) {
    console.warn('Firebase messaging is not supported in this browser');
    return null;
  }

  if (!app) app = initializeApp(firebaseConfig);
  messaging = getMessaging(app);

  try {
    getAnalytics(app);
  } catch {
    // Analytics requires a supported environment; silently skip if unavailable
  }

  return messaging;
}

export async function getPushToken(vapidKey: string): Promise<{ token: string | null; error?: string }> {
  const m = await ensureMessaging();
  if (!m) {
    return { token: null, error: 'Messaging not supported in this browser' };
  }

  // Check if service worker is supported and accessible (not blocked by iframe sandbox)
  if ('serviceWorker' in navigator) {
    try {
      // Check if we're in a cross-origin iframe (e.g. Bolt.new preview)
      if (window.self !== window.top) {
        try {
          // This will throw in cross-origin iframes
          void window.top!.location.origin;
        } catch {
          return {
            token: null,
            error: 'Push notifications require a secure origin. They work on the live website but not in this preview environment.',
          };
        }
      }

      const registrations = await navigator.serviceWorker.getRegistrations();
      if (registrations.length === 0) {
        await navigator.serviceWorker.register('/firebase-messaging-sw.js', { scope: '/' });
        // Wait for the service worker to be activated
        await navigator.serviceWorker.ready;
      }
    } catch (swError: any) {
      console.error('Service worker registration failed:', swError);
      // If it's a security/origin error, give a helpful message
      if (swError?.name === 'SecurityError' || swError?.message?.includes('origin')) {
        return { token: null, error: 'Push notifications require a secure origin (HTTPS). They work on the live website.' };
      }
      return { token: null, error: 'Service worker registration failed. Push notifications will work on the live website.' };
    }
  } else {
    return { token: null, error: 'Service workers are not supported in this browser.' };
  }

  // Request permission
  let permission: NotificationPermission;
  try {
    permission = await Notification.requestPermission();
  } catch (permError) {
    console.error('Permission request failed:', permError);
    return { token: null, error: 'Permission request failed' };
  }

  if (permission !== 'granted') {
    return { token: null, error: 'Notification permission denied. Please allow notifications in your browser settings.' };
  }

  try {
    const token = await getToken(m, { vapidKey, serviceWorkerRegistration: await navigator.serviceWorker.ready });
    if (!token) {
      return { token: null, error: 'Failed to get push token. Please try again.' };
    }
    return { token };
  } catch (tokenError: any) {
    console.error('getToken error:', tokenError);
    return { token: null, error: tokenError.message || 'Failed to get push token' };
  }
}

export async function onPushMessage(callback: (payload: any) => void): Promise<void> {
  const m = await ensureMessaging();
  if (!m) return;
  onMessage(m, callback);
}

export async function isPushSupported(): Promise<boolean> {
  const supported = await isSupported();
  return supported && 'serviceWorker' in navigator && 'PushManager' in window;
}

import { supabase } from './supabase';
import { getPushToken, onPushMessage, isPushSupported } from './firebase';

const VAPID_KEY = import.meta.env.VITE_FIREBASE_VAPID_KEY || 'BCFuwhVkBRN_fvbBq-USbzs4GJ2i59TmNrAlcLGqavXPkFtU256LeMsC4QWlK2J8MdWjL6BvBygqLu_BVVAjky4';

let lastPushError: string | null = null;

export function getLastPushError(): string | null {
  return lastPushError;
}

export async function isNotificationSupported(): Promise<boolean> {
  return await isPushSupported();
}

export async function subscribeToPush(userId: string): Promise<{ success: boolean; error?: string }> {
  lastPushError = null;

  if (!VAPID_KEY) {
    const error = 'Push notifications are not configured. Please contact support.';
    lastPushError = error;
    console.warn(error);
    return { success: false, error };
  }

  const result = await getPushToken(VAPID_KEY);

  if (!result.token) {
    const error = result.error || 'Failed to get push token';
    lastPushError = error;
    return { success: false, error };
  }

  // Delete ALL existing tokens for this user, then insert the fresh one.
  // This prevents accumulation of stale tokens across browser sessions.
  await supabase.from('push_subscriptions').delete().eq('user_id', userId);

  const { error: dbError } = await supabase
    .from('push_subscriptions')
    .insert({ user_id: userId, fcm_token: result.token, device_type: 'web' });

  if (dbError) {
    console.error('Failed to save push subscription:', dbError.message);
    lastPushError = 'Failed to save subscription to database';
    return { success: false, error: 'Failed to save subscription' };
  }

  return { success: true };
}

export async function unsubscribeFromPush(userId: string): Promise<{ success: boolean; error?: string }> {
  lastPushError = null;

  if (!VAPID_KEY) {
    return { success: false, error: 'Push notifications are not configured' };
  }

  const result = await getPushToken(VAPID_KEY);

  if (!result.token) {
    // If we can't get the token, try to delete all subscriptions for this user
    const { error: dbError } = await supabase
      .from('push_subscriptions')
      .delete()
      .eq('user_id', userId);

    if (dbError) {
      console.error('Failed to remove push subscription:', dbError.message);
      return { success: false, error: 'Failed to remove subscription' };
    }
    return { success: true };
  }

  const { error: dbError } = await supabase
    .from('push_subscriptions')
    .delete()
    .eq('user_id', userId)
    .eq('fcm_token', result.token);

  if (dbError) {
    console.error('Failed to remove push subscription:', dbError.message);
    return { success: false, error: 'Failed to remove subscription' };
  }

  return { success: true };
}

export async function listenForForegroundPush(callback: (payload: any) => void): Promise<void> {
  await onPushMessage(callback);
}

import { useEffect, useState } from 'react';
import { Search, Plus, Trash2, Save, X, Loader, GraduationCap, BookOpen, ArrowUp, ArrowDown, FileText, Award, AlertCircle, ChevronDown, ChevronRight, Download, Sparkles, Ban, Pencil } from 'lucide-react';
