import { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Bell, Filter, Calendar, AlertTriangle, BookOpen, DollarSign, Star, Info, Share2, Check, X } from 'lucide-react';
import { supabase, Notice } from '../lib/supabase';

const categories = ['all', 'academic', 'event', 'general', 'urgent', 'financial'] as const;
type Category = typeof categories[number];

const categoryIcon: Record<string, React.ElementType> = {
  academic: BookOpen,
  event: Calendar,
  urgent: AlertTriangle,
  financial: DollarSign,
  general: Info,
};

const categoryColor: Record<string, string> = {
  academic: 'bg-purple-100 text-purple-700 border-purple-200',
  event: 'bg-orange-100 text-orange-700 border-orange-200',
  urgent: 'bg-red-100 text-red-700 border-red-200',
  financial: 'bg-emerald-100 text-emerald-700 border-emerald-200',
  general: 'bg-slate-100 text-slate-700 border-slate-200',
};

const priorityBadge: Record<string, string> = {
  high: 'bg-red-500 text-white',
  medium: 'bg-blue-500 text-white',
  low: 'bg-green-500 text-white',
};

export default function NoticeBoard() {
  const [notices, setNotices] = useState<Notice[]>([]);
  const [category, setCategory] = useState<Category>('all');
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<Notice | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [searchParams, setSearchParams] = useSearchParams();

  useEffect(() => {
    const noticeId = searchParams.get('id');

    setLoading(true);
    let query = supabase
      .from('notices')
      .select('*')
      .eq('is_published', true)
      .order('created_at', { ascending: false });
    if (category !== 'all') query = query.eq('category', category);

    query.then(({ data }) => {
      const list = data ?? [];
      setNotices(list);
      setLoading(false);

      // Open notice from URL id param
      if (noticeId) {
        const target = list.find((n) => n.id === noticeId);
        if (target) {
          setSelected(target);
        } else {
          // Try direct fetch if not in filtered list
          supabase.from('notices').select('*').eq('id', noticeId).eq('is_published', true).maybeSingle().then(({ data: n }) => {
            if (n) setSelected(n);
          });
        }
      }
    });
  }, [category]);

  function shareNotice(notice: Notice, e: React.MouseEvent) {
    e.stopPropagation();
    const url = `${window.location.origin}/notices?id=${notice.id}`;
    navigator.clipboard.writeText(url).then(() => {
      setCopiedId(notice.id);
      setTimeout(() => setCopiedId(null), 2000);
    });
  }

  function closeModal() {
    setSelected(null);
    searchParams.delete('id');
    setSearchParams(searchParams);
  }

  return (
    <div className="page-enter">
      {/* Hero */}
      <section className="bg-navy-950 py-8 md:py-14">
        <div className="page-container text-center">
          <Bell className="w-8 h-8 md:w-9 md:h-9 text-gold-400 mx-auto mb-2 md:mb-3" />
          <h1 className="text-xl md:text-3xl font-serif font-bold text-white mb-1 md:mb-2">Notice Board</h1>
          <p className="text-slate-400 max-w-lg mx-auto text-xs md:text-sm">
            Official announcements, events, and updates from Aizawl Bible College.
          </p>
        </div>
      </section>

      {/* Filter bar */}
      <section className="bg-white border-b border-slate-200 sticky top-[68px] z-30">
        <div className="page-container">
          <div className="flex items-center gap-2 py-3 overflow-x-auto hide-scrollbar">
            <Filter className="w-4 h-4 text-slate-500 flex-shrink-0 mr-1" />
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setCategory(cat)}
                className={`px-4 py-1.5 text-sm font-medium rounded-full whitespace-nowrap transition-all ${
                  category === cat
                    ? 'bg-navy-800 text-white shadow-sm'
                    : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                }`}
              >
                {cat === 'all' ? 'All Notices' : cat.charAt(0).toUpperCase() + cat.slice(1)}
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Notices grid */}
      <section className="py-12 bg-slate-50">
        <div className="page-container">
          {loading ? (
            <div className="flex justify-center py-20">
              <div className="w-10 h-10 border-4 border-navy-200 border-t-navy-800 rounded-full animate-spin" />
            </div>
          ) : notices.length === 0 ? (
            <div className="text-center py-20">
              <Bell className="w-12 h-12 text-slate-300 mx-auto mb-3" />
              <h3 className="text-lg font-semibold text-slate-500">No notices found</h3>
              <p className="text-slate-400 text-sm mt-1">Try a different category filter.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
              {notices.map((notice) => {
                const CatIcon = categoryIcon[notice.category] ?? Info;
                const copied = copiedId === notice.id;
                return (
                  <button
                    key={notice.id}
                    onClick={() => setSelected(notice)}
                    className="card text-left hover:shadow-lg transition-all hover:-translate-y-0.5 flex flex-col overflow-hidden group"
                  >
                    {/* Notice image (thumbnail/banner) */}
                    {notice.image_url && (
                      <div className="w-full h-44 overflow-hidden flex-shrink-0 bg-slate-100">
                        <img
                          src={notice.image_url}
                          alt={notice.title}
                          className="w-full h-full object-cover group-hover:scale-[1.02] transition-transform duration-300"
                        />
                      </div>
                    )}
                    <div className="p-5 flex flex-col flex-1">
                      <div className="flex items-center justify-between gap-2 mb-3">
                        <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold border ${categoryColor[notice.category]}`}>
                          <CatIcon className="w-3 h-3" />
                          {notice.category.charAt(0).toUpperCase() + notice.category.slice(1)}
                        </span>
                        <div className="flex items-center gap-1.5">
                          <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold ${priorityBadge[notice.priority]}`}>
                            <Star className="w-2.5 h-2.5" />
                            {notice.priority}
                          </span>
                          <button
                            onClick={(e) => shareNotice(notice, e)}
                            title="Copy share link"
                            className={`p-1 rounded-full transition-all ${copied ? 'bg-green-100 text-green-600' : 'text-slate-400 hover:text-navy-600 hover:bg-slate-100'}`}
                          >
                            {copied ? <Check className="w-3.5 h-3.5" /> : <Share2 className="w-3.5 h-3.5" />}
                          </button>
                        </div>
                      </div>
                      <h3 className="font-semibold text-navy-900 text-base leading-snug mb-2">{notice.title}</h3>
                      <p className="text-slate-600 text-sm leading-relaxed flex-1 line-clamp-3">{notice.content}</p>
                      <p className="text-slate-400 text-xs mt-3 pt-3 border-t border-slate-100">
                        {new Date(notice.created_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' })}
                      </p>
                    </div>
                  </button>
                );
              })}
            </div>
          )}
        </div>
      </section>

      {/* Modal */}
      {selected && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm" onClick={closeModal}>
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden max-h-[90vh] flex flex-col" onClick={(e) => e.stopPropagation()}>
            {/* Banner image in modal */}
            {selected.image_url && (
              <div className="w-full h-52 flex-shrink-0 overflow-hidden bg-slate-100">
                <img src={selected.image_url} alt={selected.title} className="w-full h-full object-cover" />
              </div>
            )}
            <div className="p-6 md:p-8 overflow-y-auto">
              <div className="flex items-center gap-2 mb-4">
                <span className={`px-2.5 py-1 rounded-full text-xs font-semibold border ${categoryColor[selected.category]}`}>
                  {selected.category.charAt(0).toUpperCase() + selected.category.slice(1)}
                </span>
                <span className={`px-2 py-0.5 rounded-full text-xs font-semibold ${priorityBadge[selected.priority]}`}>
                  {selected.priority} priority
                </span>
                <div className="ml-auto flex items-center gap-2">
                  <button
                    onClick={(e) => shareNotice(selected, e)}
                    className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${copiedId === selected.id ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                  >
                    {copiedId === selected.id ? <><Check className="w-3.5 h-3.5" /> Copied!</> : <><Share2 className="w-3.5 h-3.5" /> Share</>}
                  </button>
                </div>
              </div>
              <h2 className="text-xl font-serif font-bold text-navy-900 mb-3">{selected.title}</h2>
              <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{selected.content}</p>
              <p className="text-slate-400 text-xs mt-4 pt-4 border-t border-slate-100">
                Posted: {new Date(selected.created_at).toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
              </p>
              <button onClick={closeModal} className="btn-primary mt-4 w-full justify-center">
                <X className="w-4 h-4" /> Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { useSearchParams, Link, useNavigate } from 'react-router-dom';
import {
  User, Mail, Phone, MapPin, CreditCard as Edit2, Save, X, BookOpen,
  Calendar, Loader, RefreshCw, Upload, Award, FileCheck, GraduationCap,
  CreditCard, IndianRupee, Plus, CheckCircle, AlertCircle, Sparkles, Palette,
  Ban, Bell, BellOff, CheckCheck, Clock,
  Newspaper, Pencil, Trash2, FileText, Hash,
} from 'lucide-react';
import { supabase } from '../lib/supabase';
import type { BlogPost } from '../lib/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useNotifications } from '../contexts/NotificationContext';
import { getTheme } from '../lib/themes';

type Transaction = {
  id: string;
  season: string;
  amount: number;
  payment_date: string;
  payment_method: string;
  payment_type: string;
  status: string;
  receipt_number: string | null;
  reference_no: string | null;
  notes: string | null;
};

export default function Profile() {
  const { profile, profileLoading, profileError, refreshProfile } = useAuth();
  const [searchParams, setSearchParams] = useSearchParams();
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState({
    full_name: profile?.full_name ?? '',
    phone: profile?.phone ?? '',
    address: profile?.address ?? '',
    bio: profile?.bio ?? '',
    avatar_url: profile?.avatar_url ?? '',
    course: profile?.course ?? '',
    student_year: profile?.student_year ?? '',
    admission_date: profile?.admission_date ?? '',
    ab_number: profile?.ab_number ?? '',
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [saved, setSaved] = useState(false);
  const [retrying, setRetrying] = useState(false);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const avatarInputRef = useRef<HTMLInputElement>(null);

  // Role-based themes
  const [roleThemes, setRoleThemes] = useState<Record<string, string>>({});

  // Payment state
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [transactionsLoading, setTransactionsLoading] = useState(false);
  const [showPaymentForm, setShowPaymentForm] = useState(false);
  const [txVisibilitySaving, setTxVisibilitySaving] = useState(false);
  const [paymentForm, setPaymentForm] = useState({
    amount: '',
    payment_type: 'fee' as 'fee' | 'mess',
    payment_method: 'online' as 'cash' | 'bank_transfer' | 'online' | 'cheque',
    notes: '',
  });
  const [paymentSubmitting, setPaymentSubmitting] = useState(false);
  const [paymentError, setPaymentError] = useState('');
  const [paymentSuccess, setPaymentSuccess] = useState(false);

  // My Articles (admin/faculty)
  const navigate = useNavigate();
  const [myArticles, setMyArticles] = useState<BlogPost[]>([]);
  const [articlesLoading, setArticlesLoading] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<BlogPost | null>(null);
  const [deleting, setDeleting] = useState(false);

  // Razorpay state
  const [razorpayEnabled, setRazorpayEnabled] = useState(false);
  const [razorpayKeyId, setRazorpayKeyId] = useState('');

  // Marksheet status (students)
  const [marksheetReady, setMarksheetReady] = useState(false);
  const [marksheetLoading, setMarksheetLoading] = useState(false);

  // Notifications from context
  const { notifications, unreadCount, loading: notifLoadingCtx, markAsRead, markAllAsRead, pushSupported, pushEnabled, pushError: contextPushError, enablePush, disablePush } = useNotifications();
  const [pushToggling, setPushToggling] = useState(false);
  const [localPushError, setLocalPushError] = useState<string | null>(null);
  const [pushAttempted, setPushAttempted] = useState(false);
  const pushError = pushAttempted ? (localPushError || contextPushError) : null;

  // Load role-based themes
  useEffect(() => {
    async function loadRoleThemes() {
      const { data } = await supabase
        .from('site_settings')
        .select('setting_key, setting_value')
        .like('setting_key', 'theme_%');
      if (data) {
        const themes: Record<string, string> = {};
        data.forEach((s) => {
          themes[s.setting_key] = s.setting_value;
        });
        setRoleThemes(themes);
      }
    }
    loadRoleThemes();
  }, []);

  useEffect(() => {
    if (searchParams.get('open_profile') === 'true' && profile && !profileLoading) {
      openEdit();
      searchParams.delete('open_profile');
      setSearchParams(searchParams, { replace: true });
    }
  }, [profile, profileLoading, searchParams, setSearchParams]);

  function openEdit() {
    setForm({
      full_name: profile?.full_name ?? '',
      phone: profile?.phone ?? '',
      address: profile?.address ?? '',
      bio: profile?.bio ?? '',
      avatar_url: profile?.avatar_url ?? '',
      course: profile?.course ?? '',
      student_year: profile?.student_year ?? '',
      admission_date: profile?.admission_date ?? '',
      ab_number: profile?.ab_number ?? '',
    });
    setAvatarPreview(null);
    setEditing(true);
  }

  function handleAvatarChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setAvatarPreview(reader.result as string);
    reader.readAsDataURL(file);
  }

  async function uploadAvatar(file: File): Promise<string | null> {
    const ext = file.name.split('.').pop();
    const fileName = `avatars/${profile!.id}_${Date.now()}.${ext}`;
    const { error: uploadErr } = await supabase.storage
      .from('photos')
      .upload(fileName, file, { upsert: true });

    if (uploadErr) {
      setError(uploadErr.message);
      return null;
    }

    const { data } = supabase.storage.from('photos').getPublicUrl(fileName);
    return data.publicUrl;
  }

  async function saveProfile(e: React.FormEvent) {
    e.preventDefault();
    setError('');
    setSaving(true);

    let avatarUrl = form.avatar_url;
    const file = avatarInputRef.current?.files?.[0];
    if (file) {
      setUploadingAvatar(true);
      const uploadedUrl = await uploadAvatar(file);
      if (uploadedUrl) avatarUrl = uploadedUrl;
      setUploadingAvatar(false);
    }

    const { error } = await supabase
      .from('profiles')
      .update({
        full_name: form.full_name,
        phone: form.phone,
        address: form.address,
        bio: form.bio,
        avatar_url: avatarUrl,
        course: form.course || null,
        student_year: form.student_year || null,
        admission_date: form.admission_date || null,
        ab_number: form.ab_number || null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', profile!.id);

    if (error) {
      setError(error.message);
      setSaving(false);
      return;
    }

    await refreshProfile();
    setSaving(false);
    setEditing(false);
    setSaved(true);
    setTimeout(() => setSaved(false), 2500);
  }

  async function handleRetry() {
    setRetrying(true);
    await refreshProfile();
    setRetrying(false);
  }

  // Load transactions and notifications
  useEffect(() => {
    if (!profile?.id) return;
    loadNotifications();
    loadTransactions();
    if (profile.role === 'student') {
      loadRazorpaySettings();
      loadMarksheetStatus();
    }
    if (profile.role === 'admin' || profile.role === 'faculty') {
      loadMyArticles();
    }
  }, [profile?.id, profile?.role]);

  async function loadMyArticles() {
    setArticlesLoading(true);
    const { data } = await supabase
      .from('blog_posts')
      .select('*')
      .eq('author_id', profile!.id)
      .order('created_at', { ascending: false });
    setMyArticles((data as BlogPost[]) ?? []);
    setArticlesLoading(false);
  }

  async function confirmDelete() {
    if (!deleteTarget) return;
    setDeleting(true);
    await supabase.from('blog_posts').delete().eq('id', deleteTarget.id);
    setMyArticles((prev) => prev.filter((a) => a.id !== deleteTarget.id));
    setDeleting(false);
    setDeleteTarget(null);
  }

  async function loadTransactions() {
    setTransactionsLoading(true);
    const { data } = await supabase
      .from('transactions')
      .select('*')
      .eq('user_id', profile!.id)
      .order('created_at', { ascending: false });
    setTransactions(data ?? []);
    setTransactionsLoading(false);
  }

  async function loadMarksheetStatus() {
    setMarksheetLoading(true);
    const { data } = await supabase
      .from('student_marksheets')
      .select('id')
      .eq('student_id', profile!.id)
      .maybeSingle();
    setMarksheetReady(!!data);
    setMarksheetLoading(false);
  }

  async function loadRazorpaySettings() {
    const { data } = await supabase
      .from('site_settings')
      .select('setting_key, setting_value')
      .in('setting_key', ['razorpay_enabled', 'razorpay_key_id']);
    if (data) {
      const enabledSetting = data.find((s) => s.setting_key === 'razorpay_enabled');
      if (enabledSetting) setRazorpayEnabled(enabledSetting.setting_value === 'true');
      const keyIdSetting = data.find((s) => s.setting_key === 'razorpay_key_id');
      if (keyIdSetting) setRazorpayKeyId(keyIdSetting.setting_value || '');
    }
  }

  async function loadNotifications() {
    // Provided by NotificationContext — kept as no-op for backward compatibility
  }

  async function markNotifRead(id: string) {
    await markAsRead(id);
  }

  async function markAllRead() {
    await markAllAsRead();
  }

  async function togglePush() {
    setPushAttempted(true);
    setPushToggling(true);
    setLocalPushError(null);
    try {
      if (pushEnabled) {
        const result = await disablePush();
        if (!result.success) {
          setLocalPushError(result.error || 'Failed to disable push notifications.');
        }
      } else {
        const result = await enablePush();
        if (!result.success) {
          setLocalPushError(result.error || 'Failed to enable push notifications.');
        }
      }
    } catch {
      setLocalPushError('An unexpected error occurred. Please try again.');
    }
    setPushToggling(false);
  }

  async function submitPayment(e: React.FormEvent) {
    e.preventDefault();
    setPaymentError('');
    setPaymentSubmitting(true);

    try {
      const amount = parseFloat(paymentForm.amount);

      // If Razorpay is enabled and payment method is online, use Razorpay
      if (razorpayEnabled && razorpayKeyId && paymentForm.payment_method === 'online') {
        await initiateRazorpayPayment(amount);
        return;
      }

      // Manual payment recording
      const timestamp = Date.now();
      const receiptNum = `RCP-${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}-${String(timestamp).slice(-5)}`;

      const { error: txError } = await supabase.from('transactions').insert({
        user_id: profile!.id,
        season: `Payment - ${new Date().toLocaleDateString('en-IN', { month: 'long', year: 'numeric' })}`,
        amount: amount,
        payment_type: paymentForm.payment_type,
        payment_method: paymentForm.payment_method,
        status: 'completed',
        receipt_number: receiptNum,
        notes: paymentForm.notes || null,
        recorded_by: profile!.id,
      });

      if (txError) throw txError;

      setPaymentSuccess(true);
      setTimeout(() => {
        setPaymentSuccess(false);
        setShowPaymentForm(false);
        setPaymentForm({ amount: '', payment_type: 'fee', payment_method: 'online', notes: '' });
        loadTransactions();
      }, 2000);
    } catch (err) {
      setPaymentError(err instanceof Error ? err.message : 'Payment failed. Please try again.');
    } finally {
      setPaymentSubmitting(false);
    }
  }

  async function initiateRazorpayPayment(amount: number) {
    if (!(window as any).Razorpay) {
      setPaymentError('Razorpay SDK not loaded. Please refresh the page and try again.');
      setPaymentSubmitting(false);
      return;
    }

    const timestamp = Date.now();
    const receiptNum = `RCP-${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}-${String(timestamp).slice(-5)}`;

    const options = {
      key: razorpayKeyId,
      amount: amount * 100,
      currency: 'INR',
      name: 'Aizawl Bible College',
      description: `${paymentForm.payment_type === 'fee' ? 'Fee' : 'Mess'} Payment`,
      order_id: undefined as string | undefined,
      handler: async (response: any) => {
        try {
          const { error: txError } = await supabase.from('transactions').insert({
            user_id: profile!.id,
            season: `Payment - ${new Date().toLocaleDateString('en-IN', { month: 'long', year: 'numeric' })}`,
            amount: amount,
            payment_type: paymentForm.payment_type,
            payment_method: 'online',
            status: 'completed',
            receipt_number: receiptNum,
            notes: paymentForm.notes || null,
            recorded_by: profile!.id,
            gateway: 'razorpay',
            gateway_order_id: response.razorpay_order_id,
            gateway_payment_id: response.razorpay_payment_id,
            gateway_signature: response.razorpay_signature,
          });

          if (txError) throw txError;

          setPaymentSuccess(true);
          setTimeout(() => {
            setPaymentSuccess(false);
            setShowPaymentForm(false);
            setPaymentForm({ amount: '', payment_type: 'fee', payment_method: 'online', notes: '' });
            loadTransactions();
          }, 2000);
        } catch {
          setPaymentError('Payment recorded but failed to save. Please contact admin.');
        } finally {
          setPaymentSubmitting(false);
        }
      },
      prefill: {
        name: profile?.full_name || '',
        email: profile?.email || '',
        contact: profile?.phone || '',
      },
      theme: {
        color: '#0F1B3D',
      },
      modal: {
        ondismiss: () => {
          setPaymentSubmitting(false);
          setPaymentError('Payment cancelled.');
        },
      },
    };

    const rzp = new (window as any).Razorpay(options);
    rzp.open();
    setPaymentSubmitting(false);
  }

